// 받은 f(볼트 기준 상대경로)를 옵시디언 URI 로 바꿔 302 로 넘긴다.
// VAULT/PREFIX 는 ② `출처 링크` 노드와 같은 값이어야 한다.
const VAULT  = 'LLM Wiki';
const PREFIX = 'wiki/';
const enc = (s) => encodeURIComponent(String(s));
const q = $json.query || {};
const f = String(q.f || '').replace(/^\/+/, '');
// 경로 탈출 차단 — 받은 값을 그대로 URI 에 싣기 전에 막는다.
if (!f || f.includes('..') || /^[a-z]+:/i.test(f)) {
  return [{ json: { ok: false, location: '', body: '잘못된 경로' } }];
}
const target = 'obsidian://open?vault=' + enc(VAULT) + '&file=' + enc(PREFIX + f);
return [{ json: { ok: true, location: target } }];
